// Some portions generated by Claude
// One-off generator for the dark-mode Workbench brand images (task M2.5 of
// .agent/execplans/workbench-app-shell-and-critique-fixes-20260930.md). It draws each original PNG on a canvas
// in Playwright's Chromium and rewrites dark, unsaturated pixels (lightness below 50%, saturation below 20%) to
// the dark-theme ink #e8f0f3 while keeping their alpha, so the black lettering becomes light and the orange mark
// stays as it is. Usage from the repository root:
//     node design/workbench-app-shell-plan-20260930/make-dark-logos.cjs
const fs = require('node:fs');
const path = require('node:path');
const { chromium } = require(path.resolve(__dirname, '../../e2e/node_modules/playwright'));

const IMAGES = path.resolve(__dirname, '../../tools/workbench/src/main/webapp/images');
const INK = [0xe8, 0xf0, 0xf3];

(async () => {
	const browser = await chromium.launch();
	const page = await browser.newPage();
	for (const name of ['logo', 'product']) {
		const source = fs.readFileSync(path.join(IMAGES, name + '.png')).toString('base64');
		const output = await page.evaluate(async ({ data, ink }) => {
			const image = new Image();
			image.src = 'data:image/png;base64,' + data;
			await image.decode();
			const canvas = document.createElement('canvas');
			canvas.width = image.naturalWidth;
			canvas.height = image.naturalHeight;
			const context = canvas.getContext('2d');
			context.drawImage(image, 0, 0);
			const pixels = context.getImageData(0, 0, canvas.width, canvas.height);
			let changed = 0;
			for (let index = 0; index < pixels.data.length; index += 4) {
				const [r, g, b] = [pixels.data[index], pixels.data[index + 1], pixels.data[index + 2]]
					.map((value) => value / 255);
				const max = Math.max(r, g, b);
				const min = Math.min(r, g, b);
				const lightness = (max + min) / 2;
				const saturation = max === min ? 0 : (max - min) / (1 - Math.abs(2 * lightness - 1));
				if (pixels.data[index + 3] > 0 && lightness < 0.5 && saturation < 0.2) {
					pixels.data[index] = ink[0];
					pixels.data[index + 1] = ink[1];
					pixels.data[index + 2] = ink[2];
					changed++;
				}
			}
			context.putImageData(pixels, 0, 0);
			return { changed, png: canvas.toDataURL('image/png').split(',')[1] };
		}, { data: source, ink: INK });
		fs.writeFileSync(path.join(IMAGES, name + '-dark.png'), Buffer.from(output.png, 'base64'));
		console.log(name + '-dark.png', 'pixels recolored:', output.changed);
	}
	await browser.close();
})();
